pragma solidity ^0.8.33;

/**
 * @title DecentralizedResolverStructs
 * @notice Shared structs and enums for Decentralized Resolution Module
 */
interface DecentralizedResolverStructs {
    // ============ Enums ============

    enum ResolverRole {
        NONE, // 0 - Not a resolver
        RESOLVER, // 1 - Standard resolver (appointed by senior resolver)
        SENIOR_RESOLVER, // 2 - Senior resolver (appointed by DAO/owner)
        EXTERNAL // 3 - External resolver (e.g., Kleros)
    }

    enum ResolutionOutcome {
        NONE, // 0 - No resolution yet
        RELEASE, // 1 - Funds released to recipient
        CANCEL // 2 - Funds refunded to sender
    }

    enum DisputeStatus {
        Open, // 0 - Awaiting resolver decision
        Decided, // 1 - Decision submitted, appeal window open
        Escalated, // 2 - Escalated to next round
        Final // 3 - No further appeals possible
    }

    // ============ Structs ============

    struct ResolverMetadata {
        string name;
        string description;
        uint256 appointedAt;
        address appointedBy;
        bool active;
    }

    struct DisputeMetadata {
        // Round-based tracking (DR v1)
        uint8 currentRound; // 0=initial resolver, 1=senior resolver, 2=external (Kleros)
        DisputeStatus status; // Open, Decided, Escalated, Final
        // Per-round data (fixed 3 rounds: 0, 1, 2)
        address[3] resolverAtRound; // Resolver assigned for each round
        ResolutionOutcome[3] decisionAtRound; // Decision submitted for each round
        uint256[3] decidedAtRound; // Timestamp when decision was submitted
        uint256[3] appealDeadline; // Deadline to appeal each round's decision
        // DR v2: Appeal bond tracking per round
        address[3] bondDepositorAtRound; // Who deposited appeal bond for this round
        uint256[3] bondAmountAtRound; // Appeal bond amount for this round
        address[3] bondTokenAtRound; // Token used for appeal bond
        bool[3] bondRefundedAtRound; // Whether bond was refunded (vs paid to resolvers)
        // Current state
        address escalatedBy; // Who initiated current escalation
        uint256 escalationTimestamp; // When current escalation happened
        uint256 assignedAt; // When current resolver was assigned
        uint256 resolveBy; // Deadline for current resolver to submit decision
        bytes resolutionData; // Additional resolution data
    }

    struct EscalationConfig {
        address resolver; // Resolver for this level (or address(0) for dynamic)
        uint256 fee; // Fee required to escalate to this level
        bool enabled; // Whether this level is enabled
    }

    struct PendingEscalationConfig {
        uint8 level;
        EscalationConfig config;
        uint64 eta;
        bool exists;
    }

    struct ResolutionTableEntry {
        uint8 maxRound; // Maximum round (0-2: 0=resolver only, 1=+senior, 2=+Kleros)
        uint256 escalationFee; // Fee required for escalation (legacy, use cost curves in v2)
        bool enabled; // Whether this entry is active
        string categoryName; // Human-readable category name
    }

    struct ResolverCapacity {
        uint256 maxConcurrentDisputes; // Maximum disputes resolver can handle
        uint256 currentDisputes; // Current number of active disputes
        bool acceptsNewDisputes; // Whether resolver accepts new disputes
    }

    struct ResolverStats {
        // EMA-based performance score (DR v1)
        uint256 emaScore; // EMA performance score (0-1e6 fixed point, 1e6 = perfect)
        uint256 lastScoreUpdate; // Timestamp of last EMA update
        // Objective counters
        uint256 casesAssigned; // Total cases assigned
        uint256 casesDecided; // Cases decided on time
        uint256 timeoutsAccept; // Failed to accept assignment (DR v1)
        uint256 timeoutsResolve; // Failed to resolve on time (DR v1)
        uint256 reversals; // Decisions reversed on escalation
        // Timing metrics
        uint256 totalResolutionTime; // Cumulative resolution time (for average)
        uint256 lastActive; // Last activity timestamp
        // Legacy fields (kept for backward compatibility during migration)
        uint256 disputesResolved; // Deprecated: use casesDecided
        uint256 disputesEscalated; // Deprecated: tracked separately
        uint256 qualityScore; // Deprecated: use emaScore
        // Manual controls
        uint256 assignmentWeight; // Manual override (0-10000 bps, 0=excluded)
    }

    // ============ DR v2 Structures ============

    enum CostCurveType {
        LINEAR, // cost(k) = baseCost + stepSize * k
        QUADRATIC, // cost(k) = baseCost + stepSize * k^2 (recommended default)
        GEOMETRIC // cost(k) = baseCost * multiplier^k
    }

    struct EscalationCostConfig {
        CostCurveType curveType; // Type of cost curve (DR v2)
        uint256 baseCost; // Base cost for escalation (in wei or token units)
        uint256 stepSize; // Step size for cost curve calculation
        uint256 multiplier; // Multiplier for geometric curves (r > 1, scaled by 1e18)
        address bondToken; // Token address for bond (address(0) = ETH)
        bool enabled; // Whether this cost config is enabled
    }

    struct AppealBond {
        address depositor; // Address that deposited the bond
        uint256 amount; // Bond amount
        address token; // Token address
        uint256 depositedAt; // Timestamp when bond was deposited
        bool refunded; // Whether bond has been refunded
    }
}
","keccak256":"0x69dd42715ce1e555f9c7f8c38424ae2acffc4621a78ab8479e215ccfa9c7419e","license":"Apache-2.0"},"contracts/decentralized-resolution-module/IIncentiveModule.sol":{"content":"// SPDX-License-Identifier: Apache-2.0
pragma solidity ^0.8.33;

import './DecentralizedResolverStructs.sol';

/**
 * @title IIncentiveModule
 * @notice Interface for swappable incentive modules in decentralized resolution system
 * @dev Defines the contract between DecentralizedResolutionModule and incentive logic
 *      - V1: Performance-based workload routing (no appeal bonds)
 *      - V2: Appeal bonds + escalation cost curves (no resolver staking)
 *      - V3: Resolver staking, slashing, delegation (future)
 */
interface IIncentiveModule {
    // ============ Core Lifecycle Hooks ============

    /**
     * @notice Called when a dispute is opened
     * @param workflowId Unique identifier for the dispute
     * @param token Token address for escrow
     * @param amount Escrow amount
     * @param escrowFee Fee collected from escrow
     * @param round Current round (0=initial)
     */
    function onDisputeOpened(
        uint256 workflowId,
        address token,
        uint256 amount,
        uint256 escrowFee,
        uint8 round
    ) external;

    /**
     * @notice Called when a resolver is assigned to a dispute
     * @param workflowId Unique identifier for the dispute
     * @param resolver Address of assigned resolver
     * @param round Current round
     */
    function onResolverAssigned(uint256 workflowId, address resolver, uint8 round) external;

    /**
     * @notice Called when a resolver submits a decision
     * @param workflowId Unique identifier for the dispute
     * @param resolver Address of resolver
     * @param round Current round
     * @param decision Resolution outcome
     * @param responseTime Time taken to resolve (seconds)
     */
    function onDecisionSubmitted(
        uint256 workflowId,
        address resolver,
        uint8 round,
        DecentralizedResolverStructs.ResolutionOutcome decision,
        uint256 responseTime
    ) external;

    /**
     * @notice Called when a dispute is escalated to the next round
     * @param workflowId Unique identifier for the dispute
     * @param fromRound Previous round
     * @param toRound Next round
     * @param escalatedBy Address that initiated escalation
     */
    function onEscalated(
        uint256 workflowId,
        uint8 fromRound,
        uint8 toRound,
        address escalatedBy
    ) external;

    /**
     * @notice Called when a dispute is finalized (no more appeals)
     * @param workflowId Unique identifier for the dispute
     * @param finalRound Final round that decided the outcome
     * @param finalDecision Final resolution outcome
     */
    function onDisputeFinalized(
        uint256 workflowId,
        uint8 finalRound,
        DecentralizedResolverStructs.ResolutionOutcome finalDecision
    ) external;

    /**
     * @notice Called when a resolver times out
     * @param workflowId Unique identifier for the dispute
     * @param resolver Address of resolver that timed out
     * @param round Round where timeout occurred
     * @param timeoutType Type of timeout (accept=0, resolve=1)
     */
    function onResolverTimeout(
        uint256 workflowId,
        address resolver,
        uint8 round,
        uint8 timeoutType
    ) external;

    // ============ Payment Distribution ============

    /**
     * @notice Calculate and distribute resolver payments for a finalized dispute
     * @param workflowId Unique identifier for the dispute
     * @param token Token address for payment
     * @param totalFees Total fees available for distribution
     */
    function distributePayments(uint256 workflowId, address token, uint256 totalFees) external;

    /**
     * @notice Get claimable payment for a resolver
     * @param workflowId Unique identifier for the dispute
     * @param resolver Resolver address
     * @return amount Claimable amount
     */
    function getClaimablePayment(
        uint256 workflowId,
        address resolver
    ) external view returns (uint256 amount);

    // ============ V2+ Functions (optional in V1) ============

    /**
     * @notice Check if module supports a specific feature
     * @param featureId Feature identifier (bytes4 keccak256 hash)
     * @return supported Whether the feature is supported
     * @dev Feature IDs (defined as constants in implementations):
     *      - FEATURE_APPEAL_BONDS = bytes4(keccak256("APPEAL_BONDS_V1"))
     *        Indicates module supports appeal bonds for escalation
     *      - FEATURE_PULL_ERC20_BONDS = bytes4(keccak256("PULL_ERC20_BONDS_V1"))
     *        Indicates module uses pull-based pattern for ERC20 bonds (safeTransferFrom)
     * @dev V1 implementations should return false for all features
     * @dev V2+ implementations should return true for supported features
     */
    function supportsFeature(bytes4 featureId) external view returns (bool supported);

    /**
     * @notice Get required appeal bond for escalation (V2+)
     * @param workflowId Unique identifier for the dispute
     * @param fromRound Current round
     * @param toRound Next round
     * @return bondAmount Required bond amount
     * @return token Token address for bond
     * @dev V1 implementations should return (0, address(0))
     */
    function getRequiredAppealBond(
        uint256 workflowId,
        uint8 fromRound,
        uint8 toRound
    ) external view returns (uint256 bondAmount, address token);

    /**
     * @notice Record appeal bond payment (V2+)
     * @param workflowId Unique identifier for the dispute
     * @param depositor Address that deposited bond (for ERC20: escrow contract, for ETH: user/escalator)
     * @param escalatedBy Address that initiated the escalation (always the user/escalator)
     * @param amount Bond amount
     * @param token Token address (address(0) = ETH)
     * @param round Round being appealed to
     * @dev V1 implementations should revert
     * @dev SHOULD only be callable by the escrow contract or resolution module (enforced by implementation)
     * @dev For ETH bonds (token == address(0)): MUST be payable and require(msg.value == amount)
     *      For ETH bonds, depositor MUST equal escalatedBy (user-funded)
     * @dev For ERC20 bonds: Implementation MUST pull tokens via safeTransferFrom(depositor, address(this), amount)
     *      and MUST revert on transfer failure. Depositor is typically the escrow contract (escrow-funded),
     *      but escalatedBy tracks the actual escalator for metrics/accounting.
     */
    function recordAppealBond(
        uint256 workflowId,
        address depositor,
        address escalatedBy,
        uint256 amount,
        address token,
        uint8 round
    ) external payable;

    /**
     * @notice Distribute appeal bond based on outcome (V2+)
     * @param workflowId Unique identifier for the dispute
     * @param round Round that was appealed
     * @param outcomeFlipped Whether the appeal succeeded
     * @dev V1 implementations should revert
     */
    function distributeAppealBond(uint256 workflowId, uint8 round, bool outcomeFlipped) external;
}
